// FloorStall reports the durable's ack floor (a stream sequence), how long it
// has been STALLED there, and whether it is stalled at all. Exposed so an
// adopter can publish the stall as a gauge — the signal the ack-floor monitor
// pages on — from inside the process rather than by polling consumer info a
// second time.
//
// "Stalled" is not the same as "stationary", and the difference is the whole
// correctness of the breaker. A caught-up consumer's floor sits still because
// nothing arrived, and a floor that has been still for four idle hours says
// nothing about the next message to arrive: dead-lettering that message on its
// second delivery, crediting it with a stall it did not cause, would be a
// false positive of exactly the kind this type exists to avoid. So the clock
// runs only while the consumer has delivered past its own floor — the same
// floor-versus-last-delivered comparison the incident runbook makes by hand —
// and restarts the moment the consumer catches up.
//
// The age is measured from the first observation of that stall, so a freshly
// started process under-reports an already-old one rather than over-reporting
// it: the breaker can be late, never early.
func (r *Retry) FloorStall() (floor uint64, age time.Duration, stalled bool) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if !r.haveFloor {
		return r.floor, 0, false
	}
	return r.floor, r.clock().Sub(r.floorSince), true
}

// observeFloor records one reading of the durable's ack floor against its
// last-delivered sequence, starting the stall clock when work is outstanding
// below the delivered mark and clearing it when the consumer catches up.
//
// delivered <= floor means every delivery this consumer has made is settled:
// there is no blocked message to age, whatever the floor has been doing. Note
// this stays true while a blocker waits out a ladder rung — it has been
// delivered, so Delivered stays above the floor even though nothing is
// ack-pending at that instant, which is why NumAckPending is the wrong gate
// here.
func (r *Retry) observeFloor(floor, delivered uint64, at time.Time) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.floor = floor
	if delivered <= floor {
		r.haveFloor = false
		r.stallLogged = false
		r.gapLogged = false
		return
	}
	if r.haveFloor && r.floorSince.Before(at) && r.floorAt == floor {
		return // same stall, clock runs on
	}
	r.haveFloor = true
	r.floorAt = floor
	r.floorSince = at
	r.stallLogged = false
	r.gapLogged = false
}

