package jsconsumer

import (
	"sync"
	"testing"
	"time"

	"github.com/nats-io/nats.go/jetstream"
)

// TestProbeBlockerSequenceIdentity is a throwaway probe, not a kept test.
// It answers two questions against a real server:
//
//  1. Does AckFloor.Stream+1 identify the blocker for a FILTERED consumer?
//  2. Does AckFloor.Consumer+1 identify it, and does it stay correct across
//     redeliveries (the server only recomputes adflr when the message AT the
//     floor is acked, so it may go stale)?
func TestProbeBlockerSequenceIdentity(t *testing.T) {
	nc, js := runTestEnv(t)
	if _, err := js.CreateStream(t.Context(), jetstream.StreamConfig{
		Name: "probe_v1", Subjects: []string{"probe.>"},
	}); err != nil {
		t.Fatalf("create stream: %v", err)
	}
	// Interleave so the filtered consumer's stream sequences are sparse:
	// keep -> stream 1, 4, 5.
	for _, subj := range []string{"probe.keep", "probe.skip", "probe.skip", "probe.keep", "probe.keep"} {
		if _, err := js.Publish(t.Context(), subj, []byte("x")); err != nil {
			t.Fatalf("publish: %v", err)
		}
	}

	cons, err := js.CreateOrUpdateConsumer(t.Context(), "probe_v1", jetstream.ConsumerConfig{
		Durable:       "probe",
		AckPolicy:     jetstream.AckExplicitPolicy,
		AckWait:       time.Second,
		MaxDeliver:    100,
		FilterSubject: "probe.keep",
	})
	if err != nil {
		t.Fatalf("create consumer: %v", err)
	}

	var mu sync.Mutex
	type obs struct{ streamSeq, consumerSeq, numDelivered uint64 }
	blocker := map[int]obs{} // redelivery count -> observation
	cc, err := cons.Consume(func(m jetstream.Msg) {
		meta, merr := m.Metadata()
		if merr != nil {
			return
		}
		if meta.Sequence.Stream == 4 { // the poison one
			mu.Lock()
			blocker[int(meta.NumDelivered)] = obs{meta.Sequence.Stream, meta.Sequence.Consumer, meta.NumDelivered}
			mu.Unlock()
			_ = m.NakWithDelay(200 * time.Millisecond)
			return
		}
		_ = m.Ack()
	})
	if err != nil {
		t.Fatalf("consume: %v", err)
	}
	defer cc.Stop()

	// Let it redeliver several times.
	deadline := time.Now().Add(8 * time.Second)
	for time.Now().Before(deadline) {
		mu.Lock()
		n := len(blocker)
		mu.Unlock()
		if n >= 4 {
			break
		}
		time.Sleep(50 * time.Millisecond)
	}

	info, err := cons.Info(t.Context())
	if err != nil {
		t.Fatalf("info: %v", err)
	}
	t.Logf("AckFloor.Stream=%d AckFloor.Consumer=%d Delivered.Stream=%d Delivered.Consumer=%d NumAckPending=%d",
		info.AckFloor.Stream, info.AckFloor.Consumer,
		info.Delivered.Stream, info.Delivered.Consumer, info.NumAckPending)

	mu.Lock()
	defer mu.Unlock()
	for n := 1; n <= 6; n++ {
		if o, ok := blocker[n]; ok {
			t.Logf("delivery %d: stream=%d consumer=%d | stream floor+1=%d (match=%v) | consumer floor+1=%d (match=%v)",
				n, o.streamSeq, o.consumerSeq,
				info.AckFloor.Stream+1, o.streamSeq == info.AckFloor.Stream+1,
				info.AckFloor.Consumer+1, o.consumerSeq == info.AckFloor.Consumer+1)
		}
	}
	t.Fatal("probe: see logs above")
}

