// failingFor reports the wall-clock time a message on delivery number
// `delivered` has spent failing, from the ladder it has been riding: the sum
// of the rungs already served. It is message-local and exact for a flat
// ladder — delivery 4 of a 5-minute ladder has been failing at least 15
// minutes — and conservative in general, since it counts only the scheduled
// waits and not the handler time or AckWait around them. Under-counting is
// the right direction: it can make the breaker late, never early.
func (r *Retry) failingFor(delivered int) time.Duration {
	var total time.Duration
	for n := 1; n < delivered; n++ {
		total += r.cfg.Backoff.DelayFor(n)
	}
	return total
}

