func NewRetry(cfg RetryConfig) (*Retry, error) {
	if cfg.Publisher == nil {
		return nil, errors.New("jsconsumer: RetryConfig.Publisher is required: dead-letter capture is the only terminal branch, so there is no configuration in which a message may be dropped")
	}
	if cfg.DLQSubject == "" {
		return nil, errors.New("jsconsumer: RetryConfig.DLQSubject is required: see Publisher")
	}
	if cfg.Backoff.MaxDeliver <= 0 {
		return nil, fmt.Errorf("jsconsumer: RetryConfig.Backoff.MaxDeliver must be positive, got %d: a non-positive value means unlimited redeliveries to backoff.Policy, so the dead-letter branch would never run", cfg.Backoff.MaxDeliver)
	}
	if cfg.Backoff.TermOnExhaustion {
		return nil, errors.New("jsconsumer: RetryConfig.Backoff.TermOnExhaustion must be false: this package dead-letters and Acks on exhaustion, and a bare Term neither settles the message nor leaves a record of it (ENT-1492)")
	}
	if cfg.Backoff.NakDelay <= 0 {
		return nil, fmt.Errorf("jsconsumer: RetryConfig.Backoff.NakDelay must be positive, got %s: a zero delay redelivers immediately and burns MaxDeliver in a hot loop", cfg.Backoff.NakDelay)
	}
	if cfg.Backoff.Factor > 1 && cfg.Backoff.MaxDelay <= 0 {
		return nil, errors.New("jsconsumer: RetryConfig.Backoff.MaxDelay is required with a growing Factor: an uncapped rung cannot be checked against the monitor's FloorAge")
	}
	if cfg.MinDeliveries < 0 {
		return nil, fmt.Errorf("jsconsumer: RetryConfig.MinDeliveries must not be negative, got %d", cfg.MinDeliveries)
	}
	if cfg.MinDeliveries == 0 {
		cfg.MinDeliveries = DefaultMinDeliveries
	}
	switch {
	case cfg.CaptureReserve == 0:
		cfg.CaptureReserve = DefaultCaptureReserve
	case cfg.CaptureReserve == NoCaptureReserve:
		cfg.CaptureReserve = 0
	case cfg.CaptureReserve < 0:
		return nil, fmt.Errorf("jsconsumer: RetryConfig.CaptureReserve must be -1 (NoCaptureReserve), 0 (default), or positive, got %d", cfg.CaptureReserve)
	}
	if cfg.CaptureReserve >= cfg.Backoff.MaxDeliver {
		return nil, fmt.Errorf("jsconsumer: RetryConfig.CaptureReserve (%d) leaves no deliveries for the handler out of Backoff.MaxDeliver (%d)", cfg.CaptureReserve, cfg.Backoff.MaxDeliver)
	}
	if cfg.MinDeliveries > cfg.Backoff.MaxDeliver-cfg.CaptureReserve {
		return nil, fmt.Errorf("jsconsumer: RetryConfig.MinDeliveries (%d) exceeds the ladder's %d deliveries (Backoff.MaxDeliver %d less CaptureReserve %d): the breaker could never fire before the ladder exhausted", cfg.MinDeliveries, cfg.Backoff.MaxDeliver-cfg.CaptureReserve, cfg.Backoff.MaxDeliver, cfg.CaptureReserve)
	}
	switch cfg.Breaker {
	case BreakerObserve:
	case BreakerEnforce:
		if cfg.Monitor == nil {
			return nil, errors.New("jsconsumer: RetryConfig.Breaker is BreakerEnforce but Monitor is nil: there is no stall signal to enforce on, so the breaker would silently never fire — supply the FloorMonitor here (Config.FloorMonitor alone drives the poll, not this mechanism's disposition)")
		}
	default:
		return nil, fmt.Errorf("jsconsumer: RetryConfig.Breaker is %d, want BreakerObserve or BreakerEnforce", cfg.Breaker)
	}
	if cfg.MaxTimeToDeadLetter < 0 {
		return nil, fmt.Errorf("jsconsumer: RetryConfig.MaxTimeToDeadLetter must not be negative, got %s", cfg.MaxTimeToDeadLetter)
	}
	if cfg.RecoverBy == 0 {
		cfg.RecoverBy = cfg.MinDeliveries
	}
	// One implementation of the timing arithmetic, shared with fleet CI's
	// admission lint and (when bind-only mode lands) the bind-time check
	// against the durable's real server-side config. See [Schedule].
	if err := cfg.schedule().Err(); err != nil {
		return nil, err
	}
	// Keep a failure clock for a full ladder plus the stall window, so a
	// message still riding the ladder is never swept mid-flight.
	ttl := 2 * time.Minute
	for n := 1; n <= cfg.Backoff.MaxDeliver; n++ {
		ttl += cfg.Backoff.DelayFor(n)
	}
	if cfg.Monitor != nil {
		ttl += cfg.Monitor.FloorAge()
	}
	r := &Retry{cfg: cfg, failureTTL: ttl, clock: time.Now}
	if cfg.Monitor != nil {
		r.monitor = cfg.Monitor
	}
	return r, nil
}

